sqlEquivalent:
CREATE TABLE lab_teams (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE lab_players (
  id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  team_id INTEGER NOT NULL REFERENCES lab_teams(id)
);

starterCode:
// JavaScript track — same Prisma DSL
model LabTeam {
  id Int @id @default(autoincrement())
  name String
  players LabPlayer[]
  @@map("lab_teams")
}
model LabPlayer {
  id Int @id @default(autoincrement())
  name String
  teamId Int @map("team_id")
  team LabTeam @relation(fields: [teamId], references: [id])
  @@map("lab_players")
}

